def lum(h):
    h=h.lstrip('#'); r,g,b=(int(h[i:i+2],16) for i in (0,2,4))
    def f(v):
        v/=255
        return v/12.92 if v<=0.03928 else ((v+0.055)/1.055)**2.4
    return 0.2126*f(r)+0.7152*f(g)+0.0722*f(b)
def cr(a,b):
    la,lb=lum(a),lum(b); hi,lo=max(la,lb),min(la,lb)
    return round((hi+0.05)/(lo+0.05),2)

bgs={"ink":"#0B0F0D","ink-raised":"#141A17","paper":"#F4F2EC"}
fgs={
 "river-pale":"#9FB4AD","river-avg":"#6C8474","river-lift":"#B6C9C2",
 "river-deep":"#3E5C50","bone":"#F4F2EC","bone-dim":"#C9CFCB",
 "ink":"#0B0F0D","amber(photo)":"#806339","amber-lift":"#C99A56",
}
print(f"{'fg':16}" + "".join(f"{k:>13}" for k in bgs))
for name,fg in fgs.items():
    row=f"{name:16}"
    for bk,bv in bgs.items():
        r=cr(fg,bv)
        mark="AAA" if r>=7 else ("AA " if r>=4.5 else "   ")
        row+=f"{r:>8}{mark:>5}"
    print(row)
