input.command:
python3 - <<'PY'
def lum(h):
    h=h.lstrip('#'); r,g,b=(int(h[i:i+2],16) for i in (0,2,4))
    f=lambda v:(v/255)/12.92 if v/255<=0.03928 else (((v/255)+0.055)/1.055)**2.4
    return 0.2126*f(r)+0.7152*f(g)+0.0722*f(b)
def cr(a,b):
    la,lb=lum(a),lum(b); hi,lo=max(la,lb),min(la,lb)
    return round((hi+0.05)/(lo+0.05),2)
paper="#F4F2EC"
print("light-mode river candidates on paper:")
for h in ["#375349","#2E4A40","#304A41","#2B443B"]:
    print(f"  {h}  {cr(h,paper)}  headroom over 7.0: {round(cr(h,paper)-7,2)}")
print("light-mode amber candidates on paper:")
for h in ["#6B4A1F","#5D3C11","#714508","#4A3008"]:
    print(f"  {h}  {cr(h,paper)}")
PY

