@media (min-width:60rem){ .who{grid-template-columns:22rem minmax(0,1fr);gap:var(--p-space-7)} }
.who img{inline-size:100%;block-size:auto}
.who-text{max-inline-size:var(--p-measure)}
.who-text p+p{margin-top:var(--p-space-4)}

