    add_header Strict-Transport-Security "max-age=31536000; includeSubDomains" always;
    add_header X-Content-Type-Options nosniff always;
    add_header Referrer-Policy strict-origin-when-cross-origin always;
    add_header Permissions-Policy "geolocation=(), microphone=(), camera=()" always;

    # Everything is self-hosted, so this can be strict. 'unsafe-inline' on style-src
    # covers the one inline style attribute on the hidden SVG filter block.
    add_header Content-Security-Policy "default-src 'self'; img-src 'self' data:; style-src 'self' 'unsafe-inline'; font-src 'self'; media-src 'self'; base-uri 'self'; form-action 'none'; frame-ancestors 'none'" always;

    gzip on;
    gzip_vary on;
    gzip_comp_level 6;
    gzip_min_length 1024;
    gzip_types text/plain text/css application/javascript application/json image/svg+xml application/xml;

    # Fingerprint-free filenames, so assets are cached for a week rather than a year.
    # A year on an unfingerprinted file means a palette fix does not reach anyone who
    # has already visited, which on this site would be an accessibility regression
    # nobody can see.
    location ~* \.(css|js|woff2)$ {
        expires 7d;
        add_header Cache-Control "public";
        access_log off;
    }
    location ~* \.(png|jpg|jpeg|webp|svg|m4a)$ {
        expires 30d;
        add_header Cache-Control "public";
        access_log off;
    }
    location = /index.html { add_header Cache-Control "no-cache"; }

    location / { try_files $uri $uri/ =404; }
}
